<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import TaskStatus from './TaskStatus.vue'
import type { Config, Preset, Queue, Runtime, Task } from './types'
declare global { interface Window { desktopRunner?: { getConnection(): Promise<{ apiBase:string; wsBase:string }|null>; selectExecutable(presetId?:string|null): Promise<{canceled:boolean;path?:string;matchesPreset?:boolean}> } } }
type HistoryRun={id:string;queue_name:string;trigger_source:string;state:string;started_at:string;items:Array<{task_name:string;state:string;completion_source?:string;error_summary?:string;exit_code?:number;log_summary:string[]}>}
const config=ref<Config>({schema_version:1,queues:[],tasks:[],fired_slots:[]}),runtime=ref<Runtime>({busy:false,activeTaskId:null,cooldownSeconds:0,run:null}),history=ref<HistoryRun[]>([]),presets=ref<Preset[]>([]),logs=ref<string[]>([]),selectedQueueId=ref<string|null>(null),page=ref<'queues'|'schedule'|'history'|'settings'>('queues'),message=ref('正在连接本地调度器…'),diagnostic=ref(''),connected=ref(false),closed=ref(new Set<string>());let api='',ws='',socket:WebSocket|undefined,retry:number|undefined,dragged:string|null=null
const selectedQueue=computed(()=>config.value.queues.find(q=>q.id===selectedQueueId.value)||null),book=computed(()=>new Map(config.value.tasks.map(t=>[t.id,t]))),tasks=computed(()=>selectedQueue.value?.task_ids.map(id=>book.value.get(id)).filter(Boolean) as Task[]||[])
function uid(){return crypto.randomUUID()} function draft():Task{return{id:uid(),name:'新任务',executable:'',arguments:[],working_directory:null,allow_manual_confirmation:true,allow_process_exit:true,log_path:null,success_log:null,success_log_mode:'keyword',failure_log:null,failure_log_mode:'keyword',success_log_rules:[],failure_log_rules:[],preset_id:null,preset_evidence:null,timeout_seconds:600}}
async function request(path:string,options?:RequestInit){if(!connected.value)throw new Error('后端未连接');const r=await fetch(api+path,options);if(!r.ok)throw new Error(await r.text());return r.json()} function error(title:string,e:unknown){message.value=title;diagnostic.value=e instanceof Error?e.message:String(e)}
async function load(){config.value=await request('/api/config');selectedQueueId.value??=config.value.queues[0]?.id||null;runtime.value=await request('/api/runtime');history.value=(await request('/api/history')).runs;presets.value=await request('/api/presets');message.value='后端已连接，本次实例已验证';diagnostic.value=''} async function save(){try{config.value=await request('/api/config',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(config.value)});message.value='配置已保存'}catch(e){error('保存失败（原配置保持不变）',e)}}
function addQueue(){const q:Queue={id:uid(),name:`队列 ${config.value.queues.length+1}`,task_ids:[],time_slots:[]};config.value.queues.push(q);selectedQueueId.value=q.id;void save()} function delQueue(){if(!selectedQueue.value)return;const ids=new Set(selectedQueue.value.task_ids);config.value.queues=config.value.queues.filter(q=>q.id!==selectedQueue.value?.id);config.value.tasks=config.value.tasks.filter(t=>!ids.has(t.id));selectedQueueId.value=config.value.queues[0]?.id||null;void save()} function addTask(){if(!selectedQueue.value)return;const t=draft();config.value.tasks.push(t);selectedQueue.value.task_ids.push(t.id);void save()} function removeTask(id:string){if(!selectedQueue.value)return;selectedQueue.value.task_ids=selectedQueue.value.task_ids.filter(x=>x!==id);config.value.tasks=config.value.tasks.filter(x=>x.id!==id);void save()}
function setText(t:Task,key:keyof Task,e:Event){(t as Record<string,unknown>)[key]=(e.target as HTMLInputElement).value.trim()||null;void save()} function args(t:Task,e:Event){const v=(e.target as HTMLInputElement).value.trim();t.arguments=v?v.match(/(?:[^\s"]+|"[^"]*")+/g)?.map(x=>x.replaceAll('"',''))||[]:[];void save()} function toggle(id:string){const next=new Set(closed.value);next.has(id)?next.delete(id):next.add(id);closed.value=next} function move(target:string){if(!selectedQueue.value||!dragged||dragged===target)return;const ids=selectedQueue.value.task_ids,from=ids.indexOf(dragged),to=ids.indexOf(target);ids.splice(from,1);ids.splice(to,0,dragged);dragged=null;void save()}
function selectPreset(t:Task){const p=presets.value.find(x=>x.id===t.preset_id);t.preset_evidence=p?.evidence||null;t.allow_manual_confirmation=true;t.allow_process_exit=false;message.value=p?`已选择 ${p.label}，请选择对应 EXE 后应用规则。`:'通用程序：可自行配置完成信号。';void save()} async function choose(t:Task){const r=await window.desktopRunner?.selectExecutable(t.preset_id);if(!r||r.canceled||!r.path)return;if(t.preset_id&&!r.matchesPreset){t.preset_id=null;t.preset_evidence=null;t.executable=r.path;t.working_directory=r.path.replace(/[\\/][^\\/]+$/,'');message.value='EXE 不匹配预设，已切换为通用程序。';void save();return}if(!t.preset_id){t.executable=r.path;t.working_directory=r.path.replace(/[\\/][^\\/]+$/,'');void save();return}try{Object.assign(t,await request(`/api/presets/${t.preset_id}/apply`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({executable:r.path,task_id:t.id,name:t.name})}));await save()}catch(e){error('无法应用预设规则',e)}}
async function start(){if(!selectedQueue.value)return;try{await request('/api/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({queue_id:selectedQueue.value.id})})}catch(e){error('无法启动队列',e)}} async function stop(){try{await request('/api/stop',{method:'POST'})}catch(e){error('停止请求未送达',e)}} async function confirm(id:string){try{await request('/api/confirm',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({task_id:id})})}catch(e){error('人工确认未送达',e)}}
function addSlot(){selectedQueue.value?.time_slots.push({id:uid(),enabled:true,days:[0,1,2,3,4,5,6],time:'09:00'});void save()} function removeSlot(id:string){if(selectedQueue.value){selectedQueue.value.time_slots=selectedQueue.value.time_slots.filter(x=>x.id!==id);void save()}} function day(n:number){return['一','二','三','四','五','六','日'][n]}
function events(){socket=new WebSocket(ws+'/ws');socket.onmessage=e=>{const p=JSON.parse(e.data);if(p.type==='runtime'){runtime.value=p.data;if(!p.data.busy)void load()}if(p.type==='schedule')message.value=p.data.message;if(p.type==='config')config.value=p.data;if(p.type==='log')logs.value=[...logs.value.slice(-39),p.data.message]};socket.onclose=()=>{if(connected.value){connected.value=false;message.value='实时连接断开，正在重连…';retry=window.setTimeout(init,1500)}}} async function init(){try{const c=await window.desktopRunner?.getConnection();if(!c)throw new Error('Electron 主进程没有提供本次连接。');api=c.apiBase;ws=c.wsBase;connected.value=true;await load();events()}catch(e){connected.value=false;error('无法连接本地后端',e);retry=window.setTimeout(init,2000)}} onMounted(init);onBeforeUnmount(()=>{socket?.close();if(retry)window.clearTimeout(retry)})
</script>
<template><main class="app"><aside class="side"><div class="brand">◆ <b>顺序调度</b><small>LOCAL RUNNER</small></div><nav><button :class="{active:page==='queues'}" @click="page='queues'">队列</button><button :class="{active:page==='schedule'}" @click="page='schedule'">计划</button><button :class="{active:page==='history'}" @click="page='history'">历史</button><button :class="{active:page==='settings'}" @click="page='settings'">设置</button></nav><p>仅操作本轮受管 PID，不扫描同名程序。</p></aside><section class="content"><header><div><em>CONTROL WORKBENCH</em><h1>{{page==='queues'?'任务队列':page==='schedule'?'计划管理':page==='history'?'运行历史':'连接与设置'}}</h1></div><div class="actions"><span :class="{ok:connected}">{{runtime.busy?'运行中':connected?'已连接':'未连接'}}</span><button class="primary" :disabled="runtime.busy||!selectedQueue||!connected" @click="start">开始队列</button><button class="danger" :disabled="!runtime.busy||!connected" @click="stop">全局停止</button></div></header><div class="notice">{{message}}<details v-if="diagnostic"><summary>诊断详情</summary><code>{{diagnostic}}</code></details></div>
<section v-if="page==='queues'" class="work"><aside class="queues"><div><h2>队列</h2><button :disabled="!connected||runtime.busy" @click="addQueue">新建</button></div><button v-for="q in config.queues" :key="q.id" :class="{selected:q.id===selectedQueueId}" @click="selectedQueueId=q.id">{{q.name}}<small>{{q.task_ids.length}}项</small></button><p v-if="!config.queues.length">新建队列后添加任务。</p></aside><section v-if="selectedQueue" class="board"><div class="boardhead"><input v-model="selectedQueue.name" aria-label="队列名称" @change="save"><span>{{tasks.length}} 项，严格按顺序执行</span><button class="textdanger" :disabled="runtime.busy" @click="delQueue">删除队列</button></div><article v-for="(t,index) in tasks" :key="t.id" class="task" draggable="true" @dragstart="dragged=t.id" @dragover.prevent @drop="move(t.id)"><button class="grab" title="拖拽排序">⠿</button><b class="num">{{String(index+1).padStart(2,'0')}}</b><div class="title"><input v-model="t.name" aria-label="任务名称" @change="save"><small>{{presets.find(p=>p.id===t.preset_id)?.label||'通用程序'}}</small></div><TaskStatus v-if="runtime.run?.items[index]" :state="runtime.run.items[index].state" :detail="runtime.run.items[index].error_summary"/><button @click="toggle(t.id)">{{closed.has(t.id)?'展开':'收起'}}</button><button class="textdanger" :disabled="runtime.busy" @click="removeTask(t.id)">移除</button><div v-if="!closed.has(t.id)" class="form"><label>软件预设<select v-model="t.preset_id" :disabled="runtime.busy" @change="selectPreset(t)"><option :value="null">通用程序</option><option v-for="p in presets" :key="p.id" :value="p.id">{{p.label}}</option></select></label><label class="path">程序完整路径<div><input v-model="t.executable" placeholder="请选择 .exe" @change="save"><button :disabled="runtime.busy||!connected" @click="choose(t)">选择软件</button></div></label><p v-if="t.preset_evidence" class="evidence">{{presets.find(p=>p.id===t.preset_id)?.note}}<br>证据：{{t.preset_evidence}}</p><div class="grid"><label>参数<input :value="t.arguments.join(' ')" @change="args(t,$event)"></label><label>工作目录<input :value="t.working_directory||''" @change="setText(t,'working_directory',$event)"></label><label>日志文件<input :value="t.log_path||''" placeholder="仅本轮新增行" @change="setText(t,'log_path',$event)"></label><label>超时（秒）<input v-model.number="t.timeout_seconds" type="number" min="1" @change="save"></label></div><fieldset><legend>完成信号（首个成功信号锁定）</legend><div class="signals"><label><input v-model="t.allow_manual_confirmation" type="checkbox" @change="save">人工确认</label><label><input v-model="t.allow_process_exit" type="checkbox" @change="save">正常退出</label><label>成功<input :value="t.success_log||''" placeholder="关键字或正则" @change="setText(t,'success_log',$event)"><select v-model="t.success_log_mode" @change="save"><option value="keyword">关键字</option><option value="regex">正则</option></select></label><label>失败<input :value="t.failure_log||''" placeholder="关键字或正则" @change="setText(t,'failure_log',$event)"><select v-model="t.failure_log_mode" @change="save"><option value="keyword">关键字</option><option value="regex">正则</option></select></label></div></fieldset><button v-if="runtime.activeTaskId===t.id&&t.allow_manual_confirmation" class="confirm" @click="confirm(t.id)">确认当前任务完成</button></div></article><button class="add" :disabled="runtime.busy||!connected" @click="addTask">＋ 添加任务</button></section><section v-else class="empty"><h2>没有活动队列</h2><p>从左侧新建队列。</p></section></section>
<section v-else-if="page==='schedule'" class="page"><h2>整队列定时</h2><p>到点从第一项开始；运行中到点仅记录跳过。</p><template v-if="selectedQueue"><article v-for="s in selectedQueue.time_slots" :key="s.id" class="slot"><input v-model="s.enabled" type="checkbox" @change="save"><input v-model="s.time" type="time" @change="save"><label v-for="n in 7" :key="n"><input v-model="s.days" :value="n-1" type="checkbox" @change="save">周{{day(n-1)}}</label><button class="textdanger" @click="removeSlot(s.id)">删除</button></article><button @click="addSlot">添加定时槽</button></template></section>
<section v-else-if="page==='history'" class="page"><h2>历史运行</h2><p v-if="!history.length">尚无已完成运行。</p><article v-for="r in history" :key="r.id" class="run"><b>{{r.queue_name}}</b> · {{r.trigger_source}} · {{r.state}}<ul><li v-for="i in r.items" :key="i.task_name">{{i.task_name}}：{{i.completion_source||i.error_summary||i.state}}</li></ul></article><h2>本轮日志摘要</h2><ol class="logs"><li v-for="(line,i) in logs" :key="i">{{line}}</li></ol></section>
<section v-else class="page"><h2>本地连接</h2><dl><dt>状态</dt><dd>{{connected?'本次后端实例已验证':'未连接'}}</dd><dt>数据目录</dt><dd>开发模式根目录 data\；便携版 EXE 同级 data\。</dd><dt>隐私边界</dt><dd>只保存本项目队列、历史和应用日志，不改写目标软件数据。</dd></dl><details><summary>诊断与恢复</summary><p>端口、后端和 WebSocket 异常均显示在顶部并有限重连。</p></details></section></section></main></template>
